```kotlin
import java.util.LinkedHashMap

class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        if (capacity < 1) {
            throw IllegalArgumentException("Capacity must be >= 1")
        }
    }

    private val map = object : LinkedHashMap<K, V>(capacity, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>?): Boolean {
            if (size > this@LruCache.capacity) {
                if (eldest != null) {
                    onEvict(eldest.key, eldest.value)
                }
                return true
            }
            return false
        }
    }

    operator fun get(key: K): V? = map[key]

    operator fun set(key: K, value: V) {
        map[key] = value
    }

    fun remove(key: K): V? = map.remove(key)

    val size: Int
        get() = map.size

    fun keys(): List<K> = map.keys.toList()

    operator fun contains(key: K): Boolean = map.containsKey(key)
}
