fun toJson(value: Any?, indent: Int = 0): String {
    return buildString {
        serializeValue(value, this, indent, 0)
    }
}

private fun serializeValue(
    value: Any?,
    builder: StringBuilder,
    indent: Int,
    level: Int
) {
    when (value) {
        null -> builder.append("null")
        is Boolean -> builder.append(value.toString())
        is String -> builder.append(escapeString(value))
        is Int -> builder.append(value.toString())
        is Long -> builder.append(value.toString())
        is Double -> {
            if (!value.isFinite()) {
                throw IllegalArgumentException("Non-finite double: $value")
            }
            // Use Kotlin's default toString for doubles, but ensure we don't print things like 2.0 as 2
            // The requirement says: "a whole number prints without a fraction only if it is an integer type; a Double like 2.0 prints 2.0"
            // So we just use the standard double toString which preserves .0 for doubles.
            builder.append(value.toString())
        }
        is Float -> {
            val d = value.toDouble()
            if (!d.isFinite()) {
                throw IllegalArgumentException("Non-finite float: $value")
            }
            builder.append(d.toString())
        }
        is Map<*, *> -> {
            serializeMap(value as Map<String, Any?>, builder, indent, level)
        }
        is List<*> -> {
            serializeList(value, builder, indent, level)
        }
        is Array<*> -> {
            serializeList(value.toList(), builder, indent, level)
        }
        is Enum<*> -> {
            builder.append(escapeString(value.name))
        }
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java}")
    }
}

private fun escapeString(s: String): String {
    val sb = StringBuilder()
    sb.append('"')
    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c.code < 0x20) {
                    sb.append("\\u${String.format("%04x", c.code)}")
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append('"')
    return sb.toString()
}

private fun serializeMap(
    map: Map<String, Any?>,
    builder: StringBuilder,
    indent: Int,
    level: Int
) {
    if (map.isEmpty()) {
        builder.append("{}")
        return
    }

    val entries = map.entries.toList()

    if (indent == 0) {
        builder.append("{")
        for ((i, entry) in entries.withIndex()) {
            if (i > 0) builder.append(",")
            builder.append(escapeString(entry.key))
            builder.append(":")
            serializeValue(entry.value, builder, indent, level + 1)
        }
        builder.append("}")
    } else {
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)

        builder.append("{\n")
        for ((i, entry) in entries.withIndex()) {
            builder.append(currentIndent)
            builder.append(" ") // Space before key? No, standard is usually no space after newline indent. Let's look at requirement: "a space after :"
            // The requirement says: "pretty output; each nested element on its own line indented by indent spaces per level, a space after :"

            // Standard JSON pretty print:
            // {
            //   "key": value,
            //   ...
            // }

            builder.append(escapeString(entry.key))
            builder.append(": ")
            serializeValue(entry.value, builder, indent, level + 1)

            if (i < entries.size - 1) {
                builder.append(",")
            }
            builder.append("\n")
        }
        builder.append(currentIndent)
        builder.append("}")
    }
}

private fun serializeList(
    list: List<*>,
    builder: StringBuilder,
    indent: Int,
    level: Int
) {
    if (list.isEmpty()) {
        builder.append("[]")
        return
    }

    if (indent == 0) {
        builder.append("[")
        for ((i, item) in list.withIndex()) {
            if (i > 0) builder.append(",")
            serializeValue(item, builder, indent, level + 1)
        }
        builder.append("]")
    } else {
        val currentIndent = " ".repeat(level * indent)

        builder.append("[\n")
        for ((i, item) in list.withIndex()) {
            builder.append(currentIndent)
            builder.append(" ") // Indentation for items inside the array usually matches keys or is slightly different. 
                                // Standard convention: key is at level N, value starts after colon space.
                                // Let's align with key indentation.

            serializeValue(item, builder, indent, level + 1)

            if (i < list.size - 1) {
                builder.append(",")
            }
            builder.append("\n")
        }
        builder.append(currentIndent)
        builder.append("]")
    }
}
