sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Track if we can accept a leading minus for a number
    var canAcceptLeadingMinus = true

    while (i < len) {
        val ch = input[i]

        // Skip whitespace
        if (ch.isWhitespace()) {
            i++
            continue
        }

        val startPos = i

        // Try to match operators first (longest match)
        val opSymbols = listOf("==", "!=", "<=", ">=", "<", ">", "&&", "||", "!")
        var matchedOp: Token? = null
        for (op in opSymbols) {
            if (input.startsWith(op, i)) {
                // Check if this is the longest match among valid operators
                // Since we iterate in order of decreasing length roughly, but let's be safe
                // Actually, let's just find the longest one.
                matchedOp = Token.Op(op, i)
                break // First match in this list might not be longest. Let's fix.
            }
        }

        // Better approach: find the longest operator match
        var longestOpLen = 0
        for (op in opSymbols) {
            if (input.startsWith(op, i) && op.length > longestOpLen) {
                longestOpLen = op.length
            }
        }
        if (longestOpLen > 0) {
            val symbol = input.substring(i, i + longestOpLen)
            tokens.add(Token.Op(symbol, i))
            i += longestOpLen
            canAcceptLeadingMinus = true
            continue
        }

        // Check for parentheses
        if (ch == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            canAcceptLeadingMinus = true
            continue
        }
        if (ch == ')') {
            tokens.add(Token.Paren(false, i))
            canAcceptLeadingMinus = false
            i++
            continue
        }

        // Check for string literals
        if (ch == '"' || ch == '\'') {
            val quoteChar = ch
            var j = i + 1
            val sb = StringBuilder()
            while (j < len) {
                val c = input[j]
                if (c == '\\') {
                    if (j + 1 >= len) {
                        throw TokenizeException("Unterminated string escape", i)
                    }
                    val nextChar = input[j + 1]
                    when (nextChar) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextChar)
                    }
                    j += 2
                } else if (c == quoteChar) {
                    break
                } else {
                    sb.append(c)
                    j++
                }
            }

            if (j >= len || input[j] != quoteChar) {
                throw TokenizeException("Unterminated string", i)
            }

            tokens.add(Token.Str(sb.toString(), i))
            i = j + 1
            canAcceptLeadingMinus = false
            continue
        }

        // Check for numbers or identifiers
        if (ch.isDigit() || ch == '.') {
            // It's a number start
            var j = i
            val hasDot = input[j] == '.'

            if (hasDot) {
                // Must be followed by digit? No, .5 is valid, 5. is error
                if (j + 1 >= len || !input[j + 1].isDigit()) {
                    throw TokenizeException("Malformed number", i)
                }
                j++
            }

            // Read digits
            while (j < len && input[j].isDigit()) {
                j++
            }

            // Check for optional fractional part if we didn't start with dot, or more digits after dot
            if (!hasDot) {
                // We read integer part. Check for dot and more digits
                if (j < len && input[j] == '.') {
                    if (j + 1 >= len || !input[j + 1].isDigit()) {
                        throw TokenizeException("Malformed number", i)
                    }
                    j++ // skip dot
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                }
            } else {
                // Started with dot, we already consumed one digit. Check if there are more digits or another dot
                // If we just consumed .5, j is at end of 5. 
                // Check for another dot (error) or digits
                if (j < len && input[j] == '.') {
                    throw TokenizeException("Malformed number", i)
                }
            }

            val numStr = input.substring(i, j)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, i))
            i = j
            canAcceptLeadingMinus = false
            continue
        }

        if (ch == '-' && canAcceptLeadingMinus) {
            // Check if next char is digit
            if (i + 1 < len && input[i + 1].isDigit()) {
                var j = i + 1
                val hasDot = false // Leading minus, so we look for digits then optional dot

                // Read digits
                while (j < len && input[j].isDigit()) {
                    j++
                }

                // Check for fractional part
                if (j < len && input[j] == '.') {
                    if (j + 1 >= len || !input[j + 1].isDigit()) {
                        throw TokenizeException("Malformed number", i)
                    }
                    j++ // skip dot
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                }

                val numStr = input.substring(i, j)
                val value = numStr.toDouble()
                tokens.add(Token.Num(value, i))
                i = j
                canAcceptLeadingMinus = false
                continue
            } else {
                // Minus sign not followed by digit is an error
                throw TokenizeException("Unexpected character '-'", i)
            }
        }

        // Check for identifiers
        if (ch.isLetter() || ch == '_') {
            var j = i
            while (j < len && (input[j].isLetterOrDigit() || input[j] == '_' || input[j] == '.')) {
                // Dots are only allowed after the first character? 
                // The spec says: `[A-Za-z_][A-Za-z0-9_.]*` so dots can appear anywhere in the rest.
                j++
            }
            val name = input.substring(i, j)
            tokens.add(Token.Ident(name, i))
            i = j
            canAcceptLeadingMinus = false
            continue
        }

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$ch'", i)
    }

    return tokens
}
