fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Track if we can accept a leading minus for a number
    var canAcceptLeadingMinus = true

    while (i < len) {
        val ch = input[i]

        // Skip whitespace
        if (ch.isWhitespace()) {
            i++
            continue
        }

        val startPos = i

        // Try to match operators first (longest match)
        val opSymbols = listOf("==", "!=", "<=", ">=", "&&", "||", "<", ">", "!")
        var longestOpLen = 0
        for (op in opSymbols) {
            if (input.startsWith(op, i) && op.length > longestOpLen) {
                longestOpLen = op.length
            }
        }
        if (longestOpLen > 0) {
            val symbol = input.substring(i, i + longestOpLen)
            tokens.add(Token.Op(symbol, i))
            i += longestOpLen
            canAcceptLeadingMinus = true
            continue
        }

        // Check for parentheses
        if (ch == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            canAcceptLeadingMinus = true
            continue
        }
        if (ch == ')') {
            tokens.add(Token.Paren(false, i))
            canAcceptLeadingMinus = false
            i++
            continue
        }

        // Check for string literals
        if (ch == '"' || ch == '\'') {
            val quoteChar = ch
            var j = i + 1
            val sb = StringBuilder()
            while (j < len) {
                val c = input[j]
                if (c == '\\') {
                    if (j + 1 >= len) {
                        throw TokenizeException("Unterminated string escape", i)
                    }
                    val nextChar = input[j + 1]
                    when (nextChar) {
                        'n' -> sb.append('\n')
                        't' -> sb.append('\t')
                        'r' -> sb.append('\r')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextChar)
                    }
                    j += 2
                } else if (c == quoteChar) {
                    break
                } else {
                    sb.append(c)
                    j++
                }
            }

            if (j >= len || input[j] != quoteChar) {
                throw TokenizeException("Unterminated string", i)
            }

            tokens.add(Token.Str(sb.toString(), i))
            i = j + 1
            canAcceptLeadingMinus = false
            continue
        }

        // Check for numbers or identifiers
        if (ch.isDigit() || ch == '.') {
            // It's a number start
            var j = i

            // Handle leading dot case like .5
            if (ch == '.') {
                if (j + 1 >= len || !input[j + 1].isDigit()) {
                    throw TokenizeException("Malformed number", i)
                }
                j++ // skip the dot, now we must read at least one digit
            }

            // Read digits after the optional leading dot or as integer part
            while (j < len && input[j].isDigit()) {
                j++
            }

            // Check for fractional part if we have an integer part and a dot
            if (j < len && input[j] == '.') {
                if (j + 1 >= len || !input[j + 1].isDigit()) {
                    throw TokenizeException("Malformed number", i)
                }
                j++ // skip dot
                while (j < len && input[j].isDigit()) {
                    j++
                }
            }

            val numStr = input.substring(i, j)
            val value = numStr.toDouble()
            tokens.add(Token.Num(value, i))
            i = j
            canAcceptLeadingMinus = false
            continue
        }

        if (ch == '-' && canAcceptLeadingMinus) {
            // Check if next char is digit
            if (i + 1 < len && input[i + 1].isDigit()) {
                var j = i + 1

                // Read digits
                while (j < len && input[j].isDigit()) {
                    j++
                }

                // Check for fractional part
                if (j < len && input[j] == '.') {
                    if (j + 1 >= len || !input[j + 1].isDigit()) {
                        throw TokenizeException("Malformed number", i)
                    }
                    j++ // skip dot
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                }

                val numStr = input.substring(i, j)
                val value = numStr.toDouble()
                tokens.add(Token.Num(value, i))
                i = j
                canAcceptLeadingMinus = false
                continue
            } else {
                // Minus sign not followed by digit is an error
                throw TokenizeException("Unexpected character '-'", i)
            }
        }

        // Check for identifiers
        if (ch.isLetter() || ch == '_') {
            var j = i
            while (j < len && (input[j].isLetterOrDigit() || input[j] == '_' || input[j] == '.')) {
                j++
            }
            val name = input.substring(i, j)
            tokens.add(Token.Ident(name, i))
            i = j
            canAcceptLeadingMinus = false
            continue
        }

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$ch'", i)
    }

    return tokens
