            if len(current) == 0:
                # Empty dict is a leaf value
                result[prefix] = current
            else:
                for key in current:
                    new_key = f"{prefix}{key}" if not prefix else f"{prefix}{sep}{key}"
                    _flatten(current[key], new_key)
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is a leaf value
                result[prefix] = current
            else:
                for i, item in enumerate(current):
                    new_key = f"{prefix}{sep}{i}" if prefix else str(i)
                    _flatten(item, new_key)
        else:
            # Any other value is a leaf
            result[prefix] = current

    _flatten(obj)
    return result


def unflatten(flat: dict, sep="."):
    """
    Inverse of flatten: a path segment that is a non-negative integer without leading zeros creates a list.
    Lists must be dense: indices must be exactly 0..n-1 (else ValueError).
    Conflicts raise ValueError.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    root = {}

    # Sort paths by length to process shorter paths first (parent before child)
    sorted_paths = sorted(flat.keys(), key=lambda p: len(p.split(sep)))

    for path in sorted_paths:
        value = flat[path]
        segments = _split_path(path, sep)

        if not segments:
            continue

        # Navigate/create the path
        current = root
        for i, seg in enumerate(segments):
            is_last = (i == len(segments) - 1)

            if isinstance(current, dict):
                if seg not in current:
                    # Determine what type to create
                    if is_last:
                        # Last segment: just store the value directly
                        current[seg] = value
                    else:
                        # Check next segment to decide type
                        next_seg = segments[i + 1]
                        if _is_valid_list_index(next_seg):
                            current[seg] = []
                        else:
                            current[seg] = {}
                else:
                    existing = current[seg]
                    if is_last:
                        # Conflict: key already exists
                        raise ValueError(f"Conflict: path '{path}' conflicts with existing key at '{seg}'")
                    else:
                        # Check type consistency
                        next_seg = segments[i + 1]
                        if _is_valid_list_index(next_seg):
                            if not isinstance(existing, list):
                                raise ValueError(f"Type conflict at segment '{seg}': expected list but found dict")
                        else:
                            if not isinstance(existing, dict):
                                raise ValueError(f"Type conflict at segment '{seg}': expected dict but found list")

                current = current[seg]
            elif isinstance(current, list):
                idx = int(seg)
                # Resize the list if necessary to accommodate this index
                while len(current) <= idx:
                    current.append(None)
                current = current[idx]
            else:
                raise ValueError(f"Cannot navigate through non-container at segment '{seg}'")

    # Validate that all lists are dense (no None values left)
    def validate_lists(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                validate_lists(v)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                if item is None:
                    raise ValueError(f"List is not dense: missing value at index {i}")
                validate_lists(item)

    validate_lists(root)

    return root


def _split_path(path, sep):
    """Split a path string into segments."""
    if not path:
        return []

    segments = []
    current = ""
    for char in path:
        if char == sep:
            segments.append(current)
            current = ""
        else:
            current += char
    segments.append(current)

    return segments


def _is_valid_list_index(segment):
    """Check if a segment is a valid list index (non-negative integer without leading zeros)."""
    if not segment:
        return False
    # Check if it's all digits
    if not segment.isdigit():
        return False
    # Check for leading zeros (except "0" itself)
    if len(segment) > 1 and segment[0] == '0':
        return False
    return True
