def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    """
    Evaluate an expression string according to the specified grammar.
    """
    if expr is None or expr.strip() == '':
        raise SyntaxError("Empty input")

    if env is None:
        env = {}

    # Tokenizer
    tokens = tokenize(expr)

    if not tokens:
        raise SyntaxError("Empty input")

    # Parser
    parser = Parser(tokens, env)
    result = parser.parse_expression()

    # Check for trailing tokens
    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token: {parser.tokens[parser.pos]}")

    return result


def tokenize(expr: str) -> list[str]:
    """
    Tokenize the input expression string.
    Returns a list of tokens (strings).
    Raises SyntaxError for malformed input.
    """
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]

        # Skip whitespace
        if c in ' \t\n\r':
            i += 1
            continue

        # Two-character operators
        if i + 1 < n:
            two = expr[i:i+2]
            if two == '==':
                tokens.append('==')
                i += 2
                continue
            elif two == '!=':
                tokens.append('!=')
                i += 2
                continue
            elif two == '<=':
                tokens.append('<=')
                i += 2
                continue
            elif two == '>=':
                tokens.append('>=')
                i += 2
                continue
            elif two == '||':
                tokens.append('||')
                i += 2
                continue
            elif two == '&&':
                tokens.append('&&')
                i += 2
                continue

        # Single-character operators and punctuation
        if c in '<>^+-*/%!():,?':
            tokens.append(c)
            i += 1
            continue

        # Numbers: integer or decimal
        if c.isdigit() or (c == '.' and i + 1 < n and expr[i+1].isdigit()):
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            num_str = expr[i:j]
            tokens.append(num_str)
            i = j
            continue

        # Identifiers: [A-Za-z_][A-Za-z0-9_]*
        if c.isalpha() or c == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue

        # Unknown character
        raise SyntaxError(f"Unexpected character: {c!r}")

    return tokens


class Parser:
    def __init__(self, tokens: list[str], env: dict[str, float]):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> str:
        tok = self.peek()
        if tok is None:
            raise SyntaxError("Unexpected end of input")
        self.pos += 1
        return tok

    def parse_expression(self) -> int | float:
        """Parse conditional expression (lowest precedence)."""
        return self.parse_conditional()

    def parse_conditional(self) -> int | float:
        """
        Parse a ? b : c (right-associative).
        Only the chosen branch is evaluated.
        """
        left = self.parse_or()

        if self.peek() == '?':
            self.consume()  # consume '?'

            # Evaluate left side to determine which branch to take
            if left != 0:
                # True branch: parse and evaluate true_branch (right-associative)
                true_branch = self.parse_conditional()
                if self.peek() != ':':
                    raise SyntaxError("Expected ':' after conditional expression")
                self.consume()  # consume ':'
                # False branch: skip without evaluating
                self.skip_expression()
                left = true_branch
            else:
                # False branch: expect ':' and parse/evaluate false_branch (right-associative)
                if self.peek() != ':':
                    raise SyntaxError("Expected ':' after conditional expression")
                self.consume()  # consume ':'
                false_branch = self.parse_conditional()
                left = false_branch

        return left

    def skip_expression(self):
        """Skip an expression without evaluating, consuming tokens."""
        self.skip_conditional_skip()

    def skip_conditional_skip(self):
        """Skip conditional/or/and/comparison/additive/multiplicative/unary/power/atom"""
        self.skip_or()

    def skip_or(self):
        """Skip || and && expressions."""
        self.skip_and()

        while self.peek() == '||':
            self.consume()
            self.skip_and()

    def skip_and(self):
        """Skip && expressions."""
        self.skip_comparison()

        while self.peek() == '&&':
            self.consume()
            self.skip_comparison()

    def skip_comparison(self):
        """Skip comparison expressions."""
        self.skip_additive()

        if self.peek() in ('==', '!=', '<', '<=', '>', '>='):
            self.consume()
            self.skip_additive()
            # Non-associative: no chained comparisons allowed

    def skip_additive(self):
        """Skip + and - expressions."""
        self.skip_multiplicative()

        while self.peek() in ('+', '-'):
            self.consume()
            self.skip_multiplicative()

    def skip_multiplicative(self):
        """Skip *, /, % expressions."""
        self.skip_unary()

        while self.peek() in ('*', '/', '%'):
            self.consume()
            self.skip_unary()

    def skip_unary(self):
        """Skip unary -, +, ! expressions."""
        if self.peek() in ('-', '+', '!'):
            self.consume()
            self.skip_unary()
        else:
            self.skip_power()

    def skip_power(self):
        """Skip ^ expression."""
        self.skip_atom()

        if self.peek() == '^':
            self.consume()
            self.skip_power()  # Right-associative

    def skip_atom(self):
        """Skip atom expressions."""
        tok = self.peek()

        if tok is None:
            raise SyntaxError("Unexpected end of input")

        if tok == '(':
            self.consume()
            self.skip_expression()
            if self.peek() != ')':
                raise SyntaxError("Expected ')'")
            self.consume()
            return

        # Number or identifier - just consume the token
        self.consume()

        # Check for function call
        if self.peek() == '(':
            self.consume()  # consume '('
            if self.peek() != ')':
                self.skip_expression()
                while self.peek() == ',':
                    self.consume()
                    if self.peek() == ')':
                        raise SyntaxError("Trailing comma in function call")
                    self.skip_expression()
            if self.peek() != ')':
                raise SyntaxError("Expected ')' in function call")
            self.consume()

    def parse_or(self) -> int | float:
        """Parse || then && (short-circuit)."""
        left = self.parse_and()

        while self.peek() == '||':
            self.consume()  # consume '||'
            if left != 0:
                # Short-circuit: skip parsing right side but consume tokens
                self.skip_and()
            else:
                right = self.parse_and()
                left = (1 if right != 0 else 0)

        return left

    def parse_and(self) -> int | float:
        """Parse &&."""
        left = self.parse_comparison()

        while self.peek() == '&&':
            self.consume()  # consume '&&'
            if left == 0:
                # Short-circuit: skip parsing right side but consume tokens
                self.skip_comparison()
            else:
                right = self.parse_comparison()
                left = (1 if right != 0 else 0)

        return left

    def parse_comparison(self) -> int | float:
        """Parse comparisons ==, !=, <, <=, >, >=. Non-associative."""
        left = self.parse_additive()

        cmp_ops = {'==', '!=', '<', '<=', '>', '>='}
        if self.peek() in cmp_ops:
            op = self.consume()
            right = self.parse_additive()

            if op == '==':
                left = 1 if left == right else 0
            elif op == '!=':
                left = 1 if left != right else 0
            elif op == '<':
                left = 1 if left < right else 0
            elif op == '<=':
                left = 1 if left <= right else 0
            elif op == '>':
                left = 1 if left > right else 0
            elif op == '>=':
                left = 1 if left >= right else 0

            # Non-associative: check for another comparison operator immediately after
            if self.peek() in cmp_ops:
                raise SyntaxError("Chained comparisons are not allowed")

        return left

    def parse_additive(self) -> int | float:
        """Parse + and - (left-associative)."""
        left = self.parse_multiplicative()

        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_multiplicative()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_multiplicative(self) -> int | float:
        """Parse *, /, % (left-associative)."""
        left = self.parse_unary()

        while self.peek() in ('*', '/', '%'):
            op = self.consume()
            right = self.parse_unary()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                # / on two ints gives int when it divides exactly, else float
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")
                left = left % right

        return left

    def parse_unary(self) -> int | float:
        """Parse unary -, +, !."""
        if self.peek() in ('-', '+', '!'):
            op = self.consume()
            operand = self.parse_unary()  # Right-associative for unary operators
            if op == '-':
                return -operand
            elif op == '+':
                return +operand
            elif op == '!':
                return 1 if operand == 0 else 0

        return self.parse_power()

    def parse_power(self) -> int | float:
        """Parse ^ (right-associative, binds tighter than unary minus on its left)."""
        base = self.parse_atom()

        if self.peek() == '^':
            self.consume()  # consume '^'
            exponent = self.parse_power()  # Right-associative: parse another power expression

            left = base ** exponent
            return left

        return base

    def parse_atom(self) -> int | float:
        """Parse atoms: literals, identifiers, function calls, parentheses."""
        tok = self.peek()

        if tok is None:
            raise SyntaxError("Unexpected end of input")

        # Parenthesized expression
        if tok == '(':
            self.consume()  # consume '('
            result = self.parse_expression()
            if self.peek() != ')':
                raise SyntaxError("Expected ')'")
            self.consume()  # consume ')'
            return result

        # Number literals: integer or decimal
        # Check if it's a number token (digits, or starts with digit or dot followed by digit)
        if tok.isdigit() or ('.' in tok and len(tok) > 1):
            # It's a number that contains a dot
            self.consume()
            try:
                return float(tok)
            except ValueError:
                raise SyntaxError(f"Invalid number: {tok}")

        # Pure integer token (no dots)
        if tok.isdigit():
            self.consume()
            return int(tok)

        # Decimal starting with dot like ".5"
        if tok == '.' and self.pos + 1 < len(self.tokens) and self.tokens[self.pos + 1].isdigit():
            # This case should have been tokenized as ".5" already, but handle just in case
            pass

        # Identifier: [A-Za-z_][A-Za-z0-9_]*
        if tok and (tok[0].isalpha() or tok[0] == '_'):
            self.consume()

            # Check for function call
            if self.peek() == '(':
                return self.parse_function_call(tok)
            else:
                # Variable lookup
                if tok not in self.env:
                    raise NameError(f"Unknown variable: {tok}")
                return self.env[tok]

        # Lone operators that shouldn't appear here
        if tok in ('?', ':', '|', '&', '=', '<', '>', '+', '-', '*', '/', '%', '!', '^'):
            raise SyntaxError(f"Unexpected token: {tok}")

        raise SyntaxError(f"Unexpected token: {tok}")

    def parse_function_call(self, name: str) -> int | float:
        """Parse function call: min(...), max(...), abs(...)"""
        self.consume()  # consume '('

        if name not in ('min', 'max', 'abs'):
            raise NameError(f"Unknown function: {name}")

        args = []

        # Parse first argument
        if self.peek() != ')':
            args.append(self.parse_expression())

            while self.peek() == ',':
                self.consume()  # consume ','
                if self.peek() == ')':
                    raise SyntaxError("Trailing comma in function call")
                args.append(self.parse_expression())

        if self.peek() != ')':
            raise SyntaxError("Expected ')' in function call")
        self.consume()  # consume ')'

        if name == 'abs':
            if len(args) != 1:
                raise SyntaxError(f"abs expects exactly 1 argument, got {len(args)}")
            return abs(args[0])
        elif name == 'min':
            if len(args) < 1:
                raise SyntaxError("min expects at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                if arg < result:
                    result = arg
            return result
        elif name == 'max':
            if len(args) < 1:
                raise SyntaxError("max expects at least 1 argument")
            result = args[0]
            for arg in args[1:]:
                if arg > result:
                    result = arg
            return result

        raise SyntaxError(f"Unknown function: {name}")
