import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        i = bisect.bisect_left(self._iv, (start,))
        # Check if we need to include the previous interval (touching or overlapping)
        if i > 0 and self._iv[i - 1][1] >= start:
            i -= 1
        j = i
        while j < len(self._iv) and self._iv[j][0] < end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                out.append((s, e))
                continue
            # There is overlap
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x,))
        # Check the interval at index i, or possibly i-1 if it was merged
        # Actually, bisect_left finds the first interval where (s,) >= (x,), 
        # so the candidate is self._iv[i] if i < len.
        # But we also need to check if x falls in self._iv[i-1] if that interval contains x.
        # Let's think: intervals are sorted and non-overlapping.
        # bisect_left on (x,) gives us the first interval with start >= x.
        # So x could be in self._iv[i] or in self._iv[i-1].
        if i < len(self._iv):
            s, e = self._iv[i]
            if s <= x < e:
                return True
        if i > 0:
            s, e = self._iv[i - 1]
            if s <= x < e:
                return True
        return False

    def free(self, lo, hi):
        if lo >= hi:
            return []
        gaps = []
        cur = lo
        for s, e in self._iv:
            if e <= cur:
                continue
            if s > cur:
                gaps.append((cur, min(s, hi)))
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
