import heapq
from collections import defaultdict


def route(grid: list[str]) -> tuple[int, str] | None:
    """
    Find the cheapest path from S to E in the grid.

    Returns (total_cost, moves) where moves is lexicographically smallest among cheapest paths.
    Moves order: D < L < R < T < U
    Returns None if unreachable.
    Raises ValueError for malformed grids.
    """
    # Validate grid
    if not grid or not isinstance(grid, list):
        raise ValueError("Grid must be a non-empty list of strings")

    rows = len(grid)
    cols = None

    start_pos = None
    end_pos = None
    pad_positions = defaultdict(list)  # letter -> list of (r, c)

    for r, row in enumerate(grid):
        if not isinstance(row, str):
            raise ValueError("Each row must be a string")
        if cols is None:
            cols = len(row)
        elif len(row) != cols:
            raise ValueError("Ragged rows: all rows must have equal length")

        for c, ch in enumerate(row):
            if ch == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple S cells found")
                start_pos = (r, c)
            elif ch == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple E cells found")
                end_pos = (r, c)
            elif ch == '#':
                pass  # wall
            elif ch == '.':
                pass
            elif ch.isdigit() and ch != '0':
                pass
            elif ch.islower():
                pad_positions[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character: {ch}")

    if start_pos is None:
        raise ValueError("No S cell found")
    if end_pos is None:
        raise ValueError("No E cell found")

    # Validate pad positions: each letter must appear 0 or 2 times
    for letter, positions in pad_positions.items():
        if len(positions) not in (0, 2):
            raise ValueError(f"Pad '{letter}' appears {len(positions)} times, expected 0 or 2")

    # Get directions with their order: D < L < R < T < U
    # For movement: D=(1,0), L=(0,-1), R=(0,1), U=(-1,0)
    # T is teleport

    direction_moves = [
        ('D', 1, 0),
        ('L', 0, -1),
        ('R', 0, 1),
        ('U', -1, 0),
    ]

    # Cost of a cell when moving into it
    def cell_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '#':
            return float('inf')  # wall
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1
        else:
            raise ValueError(f"Unknown character at ({r},{c}): {ch}")

    # State: (cost, move_count, moves_tuple, r, c)
    # We need lexicographically smallest moves among cheapest.
    # Use Dijkstra where state includes (cost, moves_string_or_tuple).
    # To handle the tie-breaking efficiently, we can store the best path to each state as (cost, moves_str).
    # But moves_str can be long. Instead, we use a priority queue with (cost, moves_list_as_tuple_of_chars) but that's expensive.
    # Better: since the move order is D<L<R<T<U, we can encode moves and compare lexicographically.

    # Actually, let's think about this more carefully. We want cheapest cost first, then lexicographically smallest moves.
