            if cost > prev_cost:
                continue
            if cost == prev_cost and enc_moves > prev_enc:
                continue

        # If we reached E, return the result
        if (r, c) == (end_r, end_c):
            moves_str = ''.join(chr(ord('D') + m) if m < 4 else ('T' if m == 3 else 'U') for m in enc_moves)
            # Wait, let me redo the mapping properly.
            # D=0, L=1, R=2, T=3, U=4
            rev_map = {0: 'D', 1: 'L', 2: 'R', 3: 'T', 4: 'U'}
            moves_str = ''.join(rev_map[m] for m in enc_moves)
