                    heapq.heappush(pq, (new_cost, new_enc, nr, nc))
                else:
                    prev_cost, prev_enc = best[(nr, nc)]
                    if new_cost < prev_cost or (new_cost == prev_cost and new_enc < prev_enc):
                        best[(nr, nc)] = (new_cost, new_enc)
                        heapq.heappush(pq, (new_cost, new_enc, nr, nc))

        # Teleport move: if current cell is a pad (lowercase letter), we can T to the other pad
        ch = grid[r][c]
        if ch.islower():
            # Find the other pad with the same letter
            positions = pad_positions[ch]
            if len(positions) == 2:
                for pr, pc in positions:
                    if (pr, pc) != (r, c):
                        # Teleport cost is 2
                        new_cost = cost + 2
                        new_enc = enc_moves + (move_order['T'],)

                        if (pr, pc) not in best:
                            best[(pr, pc)] = (new_cost, new_enc)
                            heapq.heappush(pq, (new_cost, new_enc, pr, pc))
                        else:
                            prev_cost, prev_enc = best[(pr, pc)]
                            if new_cost < prev_cost or (new_cost == prev_cost and new_enc < prev_enc):
                                best[(pr, pc)] = (new_cost, new_enc)
                                heapq.heappush(pq, (new_cost, new_enc, pr, pc))

    # If we exit the loop without reaching E
    return None
