    """Resolve ${key} and ${section:key} references in a value."""
    if not isinstance(value, str):
        return value

    result = []
    i = 0
    while i < len(value):
        if value[i] == '$':
            if i + 1 < len(value) and value[i + 1] == '$':
                # Literal $
                result.append('$')
                i += 2
            elif i + 1 < len(value) and value[i + 1] == '{':
