                    raise ValueError(f"Unterminated interpolation reference")

                ref_str = value[i + 2:close_idx]
                ref_key, ref_section = _parse_reference(ref_str, current_section)

                # Check for cycles
                ref_tuple = (ref_section, ref_key)
                if ref_tuple in visited:
                    raise ValueError(f"Reference cycle detected involving {ref_tuple}")

                new_visited = visited | {ref_tuple}

                # Look up the reference
                if ref_section in sections and ref_key in sections[ref_section]:
                    ref_value = sections[ref_section][ref_key]
                    resolved = _resolve_interpolation(ref_value, ref_section, sections, new_visited)
                    result.append(resolved)
                else:
                    raise ValueError(f"Undefined reference: ${ref_str}")

                i = close_idx + 1
            else:
                # Just a $ not followed by { or $
                result.append('$')
                i += 1
        else:
            result.append(value[i])
            i += 1

    return ''.join(result)


def _parse_reference(ref_str: str, current_section: str) -> tuple[str, str]:
    """Parse a reference string like 'key' or 'section:key'."""
    if ':' in ref_str:
        parts = ref_str.split(':', 1)
        section = parts[0].strip()
        key = parts[1].strip().lower()
        return (key, section)
    else:
        key = ref_str.strip().lower()
        return (key, current_section)
