import re
from typing import List, Optional, Tuple


class Version:
    """Represents a Semantic Version 2.0.0."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List[str]] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # List of strings/ints
        self.build = build

    def __repr__(self):
        s = f"Version({self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f", prerelease={self.prerelease}"
        if self.build:
            s += f", build={self.build}"
        s += ")"
        return s

    def __str__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(str(p) for p in self.prerelease)
        if self.build:
            s += "+" + self.build
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        # Equality follows precedence rules, but build metadata is ignored
        return self._cmp_key() == other._cmp_key()

    def __hash__(self):
        # Hash based on the full version including build for dict keys, but equality ignores build
        # Actually, if __eq__ ignores build, __hash__ should also ignore build to be consistent
        key = (self.major, self.minor, self.patch, tuple(self.prerelease) if self.prerelease else None)
        return hash(key)

    def _cmp_key(self):
        """Returns a tuple for comparison. Build metadata is ignored."""
        # For prerelease: a version without prerelease has higher precedence than one with
        # If both have prerelease, compare identifiers
        pre = self.prerelease
        if pre is None:
            pre_tuple = ()
        else:
            # Convert to tuple of (is_numeric, value) for proper comparison
            pre_tuple = tuple((p.isdigit(), int(p) if p.isdigit() else p) for p in pre)

        return (self.major, self.minor, self.patch, False if pre is None else True, pre_tuple)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()


def parse(v: str) -> Version:
    """Parse a semantic version string."""
    if not isinstance(v, str):
        raise ValueError(f"Invalid version: {v}")

    # Remove leading 'v' or '='
    s = v.strip()
    if s.startswith('v') or s.startswith('V'):
        s = s[1:]
    if s.startswith('='):
        s = s[1:]
    s = s.strip()

    if not s:
        raise ValueError(f"Invalid version: {v}")

