def satisfies(version_str: str, range_str: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        v = parse(version_str)
    except ValueError:
        raise ValueError(f"Invalid version: {version_str}")

    try:
        sets = parse_range(range_str)
    except ValueError as e:
        raise ValueError(f"Invalid range: {range_str} - {e}")

    for comparators in sets:
        if _satisfies_set(v, comparators):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Find the highest version that satisfies the range."""
    try:
        parsed_sets = parse_range(rng)
    except ValueError as e:
        raise ValueError(f"Invalid range: {rng} - {e}")

    valid_versions = []
    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        for comparators in parsed_sets:
            if _satisfies_set(v, comparators):
                valid_versions.append((v, v_str))
                break

    if not valid_versions:
        return None

    # Sort by version precedence and return the highest
    valid_versions.sort(key=lambda x: x[0], reverse=True)
    return valid_versions[0][1]
