        has_matching_prerelease_comparator = False
        for op, comp_ver in comparators:
            if _has_same_major_minor_patch(version, comp_ver) and _is_prerelease(comp_ver):
                has_matching_prerelease_comparator = True
                break

        if not has_matching_prerelease_comparator:
            return False

    return True


def parse_range(rng: str) -> List[List[Tuple[str, Version]]]:
    """Parse a range string into a list of comparator sets.

    Each set is a list of (operator, version) tuples.
    The range matches if any set matches.
    """
    rng = rng.strip()
    if not rng:
        raise ValueError(f"Invalid range: {rng}")

    # Split by ||
    or_parts = rng.split('||')
    sets = []

    for or_part in or_parts:
        or_part = or_part.strip()
        if not or_part:
            raise ValueError(f"Invalid range: {rng}")

        comparators = _parse_comparator_set(or_part)
        sets.append(comparators)

    return sets


def _parse_comparator_set(s: str) -> List[Tuple[str, Version]]:
    """Parse a comparator set (whitespace-separated comparators)."""
    s = s.strip()
    if not s:
        raise ValueError(f"Invalid comparator set")

    # Check for * or empty
    if s == '*' or s == '':
        return []

    # Split by whitespace
    tokens = s.split()
    comparators = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        op = ''
        ver_str = token

        # Check for operator prefixes
        if token.startswith('>='):
            op = '>='
            ver_str = token[2:]
        elif token.startswith('<='):
            op = '<='
            ver_str = token[2:]
        elif token.startswith('>'):
            op = '>'
            ver_str = token[1:]
        elif token.startswith('<'):
            op = '<'
            ver_str = token[1:]
        elif token.startswith('='):
            op = '='
            ver_str = token[1:]
        elif token.startswith('~'):
            op = '~'
            ver_str = token[1:]
        elif token.startswith('^'):
            op = '^'
            ver_str = token[1:]

        if not ver_str:
            raise ValueError(f"Invalid comparator: {token}")

        # Check for hyphen range: version - version
        if i + 2 < len(tokens) and tokens[i+1] == '-':
            upper_ver_str = tokens[i+2]
            lower, upper = _expand_hyphen_range(ver_str, upper_ver_str)
            comparators.append(('>=', lower))
            comparators.append(('<=', upper))
            i += 3
            continue

        # Parse version
        try:
            v, is_x = _parse_partial_version(ver_str)
        except ValueError:
            raise ValueError(f"Invalid version in comparator: {ver_str}")

        # Handle special operators
        if op == '~':
            lower, upper = _expand_tilde(v)
            comparators.append(('>=', lower))
            comparators.append(('<', upper))
        elif op == '^':
            lower, upper = _expand_caret(v)
            comparators.append(('>=', lower))
            comparators.append(('<', upper))
        else:
            # For partial versions with <, >, <=, >=, we need to expand them
            if is_x:
                # X-range expansion
                if op == '<':
                    # 1.x means <2.0.0, 1.2.x means <1.3.0
                    if v.patch == 0 and v.minor == 0:
                        upper = Version(v.major + 1, 0, 0, None, None)
                    elif v.patch == 0:
                        upper = Version(v.major, v.minor + 1, 0, None, None)
                    else:
                        # Should not happen for X-ranges with patch
                        upper = Version(v.major, v.minor, v.patch + 1, None, None)
                    comparators.append(('<', upper))
                elif op == '<=':
                    if v.patch == 0 and v.minor == 0:
                        lower = Version(v.major, 0, 0, None, None)
                        upper = Version(v.major + 1, 0, 0, None, None)
                    elif v.patch == 0:
                        lower = Version(v.major, v.minor, 0, None, None)
                        upper = Version(v.major, v.minor + 1, 0, None, None)
                    else:
                        lower = Version(v.major, v.minor, v.patch, None, None)
                        upper = Version(v.major, v.minor, v.patch + 1, None, None)
                    comparators.append(('>=', lower))
                    comparators.append(('<', upper))
                elif op == '>=':
                    if v.patch == 0 and v.minor == 0:
                        lower = Version(v.major, 0, 0, None, None)
                    elif v.patch == 0:
                        lower = Version(v.major, v.minor, 0, None, None)
                    else:
                        lower = Version(v.major, v.minor, v.patch, None, None)
                    comparators.append(('>=', lower))
                elif op == '>':
                    if v.patch == 0 and v.minor == 0:
                        lower = Version(v.major + 1, 0, 0, None, None)
                    elif v.patch == 0:
                        lower = Version(v.major, v.minor + 1, 0, None, None)
                    else:
                        lower = Version(v.major, v.minor, v.patch + 1, None, None)
                    comparators.append(('>=', lower))
                elif op == '=' or op == '':
                    # X-range with = or no operator means any version in that range
                    if v.patch == 0 and v.minor == 0:
                        lower = Version(v.major, 0, 0, None, None)
                        upper = Version(v.major + 1, 0, 0, None, None)
                    elif v.patch == 0:
                        lower = Version(v.major, v.minor, 0, None, None)
                        upper = Version(v.major, v.minor + 1, 0, None, None)
                    else:
                        lower = Version(v.major, v.minor, v.patch, None, None)
                        upper = Version(v.major, v.minor, v.patch + 1, None, None)
                    comparators.append(('>=', lower))
                    comparators.append(('<', upper))
            else:
                # Full version with operator
                comparators.append((op, v))

        i += 1

    return comparators


def _expand_hyphen_range(lower_str: str, upper_str: str) -> Tuple[Version, Version]:
    """Expand a hyphen range lower - upper."""
    lower_v, lower_is_x = _parse_partial_version(lower_str)
    upper_v, upper_is_x = _parse_partial_version(upper_str)

    # Lower bound is inclusive, fill zeros
    if lower_is_x:
        if lower_v.patch == 0 and lower_v.minor == 0:
            lower_full = Version(lower_v.major, 0, 0, None, None)
        elif lower_v.patch == 0:
            lower_full = Version(lower_v.major, lower_v.minor, 0, None, None)
        else:
            lower_full = lower_v
    else:
        lower_full = lower_v

    # Upper bound is exclusive of the next patch/minor/major
    if upper_is_x:
        if upper_v.patch == 0 and upper_v.minor == 0:
            upper_full = Version(upper_v.major + 1, 0, 0, None, None)
        elif upper_v.patch == 0:
            upper_full = Version(upper_v.major, upper_v.minor + 1, 0, None, None)
        else:
            upper_full = Version(upper_v.major, upper_v.minor, upper_v.patch + 1, None, None)
    else:
        # Upper bound is inclusive in the range, but we convert to < next
        if upper_v.patch == 0 and upper_v.minor == 0:
            upper_full = Version(upper_v.major + 1, 0, 0, None, None)
        elif upper_v.patch == 0:
            upper_full = Version(upper_v.major, upper_v.minor + 1, 0, None, None)
        else:
            upper_full = Version(upper_v.major, upper_v.minor, upper_v.patch + 1, None, None)

    return lower_full, upper_full


def satisfies(version_str: str, range_str: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        v = parse(version_str)
    except ValueError:
        raise ValueError(f"Invalid version: {version_str}")

    try:
        sets = parse_range(range_str)
    except ValueError as e:
        raise ValueError(f"Invalid range: {range_str} - {e}")

    for comparators in sets:
        if _satisfies_set(v, comparators):
            return True

    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Find the highest version that satisfies the range."""
    try:
        parsed_sets = parse_range(rng)
    except ValueError as e:
        raise ValueError(f"Invalid range: {rng} - {e}")

    valid_versions = []
    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        for comparators in parsed_sets:
            if _satisfies_set(v, comparators):
                valid_versions.append((v, v_str))
                break

    if not valid_versions:
        return None

    # Sort by version precedence and return the highest
    valid_versions.sort(key=lambda x: x[0], reverse=True)
    return valid_versions[0][1]
