def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: Environment variables dictionary.

    Returns:
        A list of words after parsing and expansion.

    Raises:
        ValueError: For unterminated quotes, unterminated ${, or trailing backslash.
    """

    def expand_var(name: str, default_info: tuple[str, bool] | None) -> str:
        value = env.get(name)
        if value is not None:
            return value
        else:
            if default_info is not None:
                default_text, _ = default_info
                expanded_default, _ = _expand_part(default_text, env, in_quotes=True)
                return expanded_default
            return ""

    def _expand_part(text: str, env: dict[str, str], in_quotes: bool) -> tuple[str, bool]:
        result = []
        i = 0
        n = len(text)

        while i < n:
            c = text[i]

            if in_quotes:
                if c == '$':
                    i += 1
                    if i < n and text[i] == '{':
                        i += 1
                        name, end_idx, default = _parse_brace_var(text, i)
                        expanded = expand_var(name, default)
                        result.append(expanded)
                        i = end_idx
                    elif i < n and (text[i].isalpha() or text[i] == '_'):
                        ns = i
                        while i < n and (text[i].isalnum() or text[i] == '_'):
                            i += 1
                        name = text[ns:i]
                        expanded = expand_var(name, None)
                        result.append(expanded)
                    else:
                        result.append('$')
                elif c == '\\' and i + 1 < n:
                    nc = text[i + 1]
                    if nc in ('$', '"', '\\', '\n'):
                        if nc == '\n':
                            i += 2
                        else:
                            result.append(nc)
                            i += 2
                    else:
                        result.append('\\')
                        i += 1
                elif c == '"':
                    break
                else:
                    result.append(c)
                    i += 1
            else:
                if c == '$':
                    i += 1
                    if i < n and text[i] == '{':
                        i += 1
                        name, end_idx, default = _parse_brace_var(text, i)
                        expanded = expand_var(name, default)
                        result.append(expanded)
                        i = end_idx
                    elif i < n and (text[i].isalpha() or text[i] == '_'):
                        ns = i
                        while i < n and (text[i].isalnum() or text[i] == '_'):
                            i += 1
                        name = text[ns:i]
                        expanded = expand_var(name, None)
                        result.append(expanded)
                    else:
                        result.append('$')
                elif c == '\\' and i + 1 < n:
                    i += 1
                    result.append(text[i])
                    i += 1
                elif c == '\\' and i + 1 == n:
                    raise ValueError("Trailing unescaped backslash")
                else:
                    result.append(c)
                    i += 1

        return ''.join(result), not in_quotes

    def _parse_brace_var(text: str, start: int) -> tuple[str, int, tuple[str, bool] | None]:
        i = start
        n = len(text)

        if i >= n or not (text[i].isalpha() or text[i] == '_'):
            raise ValueError("Invalid variable name")

        ns = i
        while i < n and (text[i].isalnum() or text[i] == '_'):
            i += 1
        name = text[ns:i]

        if i >= n:
            raise ValueError("Unterminated ${}")

        if text[i] == '}':
            return (name, i + 1, None)
        elif text[i] == ':' and i + 1 < n and text[i + 1] == '-':
            i += 2
            ds = i
            depth = 1
            while i < n and depth > 0:
                if text[i] == '{':
                    depth += 1
                elif text[i] == '}':
                    depth -= 1
                    if depth == 0:
                        break
                i += 1
            if depth != 0:
                raise ValueError("Unterminated ${}")
            return (name, i + 1, (text[ds:i], True))
        elif text[i] == '-':
            i += 1
            ds = i
            depth = 1
            while i < n and depth > 0:
                if text[i] == '{':
                    depth += 1
                elif text[i] == '}':
                    depth -= 1
                    if depth == 0:
                        break
                i += 1
            if depth != 0:
                raise ValueError("Unterminated ${}")
            return (name, i + 1, (text[ds:i], False))
        else:
            raise ValueError(f"Unexpected char '{text[i]}'")

    n = len(line)
    i = 0

    # Build words as lists of parts where each part is (content, is_quoted_fragment)
    words_raw = []  # List of word_parts where each word_parts is [(content, is_quoted), ...]
    current_word_parts: list[tuple[str, bool]] = []

    def flush_current_word():
        if not current_word_parts:
            return

        joined = ''.join(content for content, _ in current_word_parts)
        is_entirely_quoted = all(is_q for _, is_q in current_word_parts)

        if is_entirely_quoted:
            # No field splitting - the entire word is quoted
            words_raw.append([joined])
        else:
            # Field splitting applies to unquoted expansions
            # Split on whitespace (spaces, tabs, newlines)
            parts = joined.split()
            for part in parts:
                words_raw.append([part])

        current_word_parts.clear()

    while i < n:
        c = line[i]

        if c in (' ', '\t', '\n'):
            flush_current_word()
            i += 1
        elif c == "'":
            i += 1
            start = i
            while i < n and line[i] != "'":
                i += 1
            if i >= n:
                raise ValueError("Unterminated single quote")
            content = line[start:i]
            current_word_parts.append((content, True))
            i += 1
        elif c == '"':
            i += 1
            start = i
            depth = 0
            while i < n:
                if line[i] == '\\' and i + 1 < n:
                    nc = line[i + 1]
                    if nc in ('$', '"', '\\', '\n'):
                        if nc == '\n':
                            i += 2
                        else:
                            i += 2
                    else:
                        i += 1
                elif line[i] == '$' and i + 1 < n and line[i + 1] == '{':
                    i += 2
                    depth += 1
                elif line[i] == '}' and depth > 0:
                    depth -= 1
                    i += 1
                elif line[i] == '"':
                    if depth == 0:
                        break
                    else:
                        i += 1
                else:
                    i += 1

            if i >= n:
                raise ValueError("Unterminated double quote")

            content = line[start:i]
            expanded, is_q = _expand_part(content, env, in_quotes=True)
            current_word_parts.append((expanded, True))
            i += 1
        elif c == '\\' and i + 1 < n:
            i += 1
            content = line[i]
            current_word_parts.append((content, False))
            i += 1
        elif c == '\\' and i + 1 == n:
            raise ValueError("Trailing unescaped backslash")
        else:
            start = i
            while i < n and line[i] not in (' ', '\t', '\n', "'", '"', '\\'):
                if line[i] == '$':
                    break
                i += 1

            if i > start:
                content = line[start:i]
                expanded, is_q = _expand_part(content, env, in_quotes=False)
                current_word_parts.append((expanded, False))

    flush_current_word()

    # Flatten the words
    result = []
    for word_list in words_raw:
        for item in word_list:
            result.append(item)

    return result
