from __future__ import annotations

import dataclasses
import typing
from typing import Any, get_type_hints, get_origin, get_args


class LoadError(ValueError):
    """Exception raised when loading a dataclass from JSON-like data fails."""

    def __init__(self, path: str, message: str = ""):
        self.path = path
        if message:
            super().__init__(f"{path}: {message}")
        else:
            super().__init__(path)


def _get_type_hints_safe(cls):
    """Get type hints for a dataclass, handling forward references."""
    try:
        return get_type_hints(cls)
    except Exception:
        raise


def _load_value(cls: type, data: Any, path: str) -> Any:
    """Load a value of type cls from data at the given path."""

    # Handle NoneType
    if cls is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {type(data).__name__}")

    # Handle basic types: int, float, str, bool
    if cls is int:
        if isinstance(data, bool):  # bool is subclass of int in Python, reject it
            raise LoadError(path, f"expected int, got bool")
        if isinstance(data, int):
            return data
        raise LoadError(path, f"expected int, got {type(data).__name__}")

    if cls is float:
        if isinstance(data, bool):  # reject bool for float too
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, (int, float)):
            return float(data)
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if cls is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    if cls is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    # Handle Optional[T] or T | None or Union types
    origin = get_origin(cls)
    args = get_args(cls)

    # Check for Union (including | syntax which becomes Union in runtime)
    if origin is typing.Union:
        none_type = type(None)
        non_none_types = [arg for arg in args if arg is not none_type]

        if data is None:
            # If it's Optional or T|None, None is acceptable
            if len(non_none_types) > 0:
                return None
            else:
                raise LoadError(path, f"expected None, got {type(data).__name__}")

        if len(non_none_types) == 1:
            # This is Optional[T] or T | None with non-null data
            inner_type = non_none_types[0]
            try:
                return _load_value(inner_type, data, path)
            except LoadError as e:
                raise e

        if len(non_none_types) > 1:
            # Union of multiple types (not including None since we handled None above)
            # Try each type in order
            last_error = None
            for inner_type in non_none_types:
                try:
                    return _load_value(inner_type, data, path)
                except LoadError as e:
                    last_error = e
            if last_error:
                raise last_error
            # If no type matched and data is not None, we should report an error
            raise LoadError(path, f"could not load any type from union {cls}")

        # Union with only None? That would be Optional[None] which is just None, already handled
        if len(non_none_types) == 0:
            if data is None:
                return None
            raise LoadError(path, f"expected None, got {type(data).__name__}")

    # Handle Literal[...]
    if origin is typing.Literal:
        literal_values = args
        # Check if data matches one of the literal values
        for val in literal_values:
            if data == val and type(data) == type(val):
                return val
        raise LoadError(path, f"expected one of {literal_values}, got {repr(data)}")

    # Handle list[T]
    if origin is list or (hasattr(typing, '_GenericAlias') and isinstance(cls, typing._GenericAlias) and get_origin(cls) is list):
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")
        inner_type = args[0] if args else Any
        result = []
        for i, item in enumerate(data):
            try:
                result.append(_load_value(inner_type, item, f"{path}[{i}]"))
            except LoadError as e:
                raise e
        return result

    # Handle dict[str, T]
    if origin is dict or (hasattr(typing, '_GenericAlias') and isinstance(cls, typing._GenericAlias) and get_origin(cls) is dict):
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")
        key_type = args[0] if len(args) > 0 else str
        value_type = args[1] if len(args) > 1 else Any

        # For now, assume keys are strings as per the spec (dict[str, T])
        result = {}
        for key in data:
            if not isinstance(key, str):
                raise LoadError(path, f"expected string key, got {type(key).__name__}")
            try:
                result[key] = _load_value(value_type, data[key], f"{path}.{key}")
            except LoadError as e:
                raise e
        return result

    # Handle tuple[T, ...] (variable length)
    if origin is tuple:
        args_list = args

        # Check if it's a variable-length tuple (tuple[T, ...])
        if len(args_list) >= 2 and args_list[-1] is Ellipsis:
            # Variable length tuple
            inner_type = args_list[0]
            if not isinstance(data, list):
                raise LoadError(path, f"expected list/tuple, got {type(data).__name__}")
            result = []
            for i, item in enumerate(data):
                try:
                    result.append(_load_value(inner_type, item, f"{path}[{i}]"))
                except LoadError as e:
                    raise e
            return tuple(result)
        else:
            # Fixed length tuple
            if not isinstance(data, list):
                raise LoadError(path, f"expected list/tuple, got {type(data).__name__}")
            if len(args_list) != len(data):
                raise LoadError(path, f"expected tuple of length {len(args_list)}, got {len(data)}")
            result = []
            for i, item in enumerate(data):
                inner_type = args_list[i]
                try:
                    result.append(_load_value(inner_type, item, f"{path}[{i}]"))
                except LoadError as e:
                    raise e
            return tuple(result)

    # Handle dataclasses
    if dataclasses.is_dataclass(cls):
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

        # Get type hints
        try:
            hints = _get_type_hints_safe(cls)
        except Exception as e:
            raise LoadError(path, f"could not get type hints for {cls.__name__}: {e}")

        # Check for unknown keys first
        fields_map = {}
        field_defaults = {}
        field_has_default = {}

        for field in dataclasses.fields(cls):
            fields_map[field.name] = field
            if field.default is not dataclasses.MISSING:
                field_defaults[field.name] = field.default
                field_has_default[field.name] = True
            elif field.default_factory is not dataclasses.MISSING:
                field_defaults[field.name] = field.default_factory
                field_has_default[field.name] = True
            else:
                field_has_default[field.name] = False

        # Check for unknown keys
        for key in data:
            if key not in fields_map:
                raise LoadError(path, f"unknown key '{key}'")

        # Build instance
        kwargs = {}
        for field in dataclasses.fields(cls):
            name = field.name
            if name in data:
                try:
                    value = _load_value(hints[name], data[name], f"{path}.{name}")
                    kwargs[name] = value
                except LoadError as e:
                    raise e
            elif field_has_default[name]:
                if callable(field_defaults[name]):
                    kwargs[name] = field_defaults[name]()
                else:
                    kwargs[name] = field_defaults[name]
            else:
                raise LoadError(path, f"missing required field '{name}'")

        return cls(**kwargs)

    # Handle Any or other unhandled types
    if cls is Any:
        return data

    # Fallback: try to use the type directly
    # This might fail for complex types, but let's try
    raise LoadError(path, f"unsupported type annotation: {cls}")


def load(cls: type, data: Any) -> Any:
    """Load an instance of a dataclass from JSON-like data."""
    return _load_value(cls, data, "$")
