# Summarizes web server access logs in combined log format.

if [ $# -eq 0 ]; then
    echo "Usage: solution.sh LOGFILE..." >&2
    exit 1
fi

# Check that all input files exist (unless it's '-')
for f in "$@"; do
    if [ "$f" != "-" ] && [ ! -e "$f" ]; then
        echo "Error: file not found: $f" >&2
        exit 1
    fi
done

# Determine how to read the files
read_command() {
    local f="$1"
    if [ "$f" = "-" ]; then
        cat
    elif [[ "$f" == *.gz ]]; then
        zcat "$f"
    else
        cat "$f"
    fi
}

# Combine all inputs into a single stream
combined_input() {
    for f in "$@"; do
        read_command "$f"
    done
}

# Process all lines with awk
combined_input | awk '
BEGIN {
    requests = 0
    malformed = 0
}
{
    line = $0

    # Split by double quotes to get the request line and other quoted fields.
    n = split(line, parts, "\"")

    # Expected structure when splitting by ":
    # parts[1] = "IP ident user [date] " 
    # parts[2] = request line (e.g., "GET /path HTTP/1.1")
    # parts[3] = ' status size ' (space, status, space, size, space)
    # parts[4] = referer
    # parts[5] = ' ' (space between referer and user-agent quotes)
    # parts[6] = user-agent

    if (n != 7) {
        malformed++
        next
    }

    prefix = parts[1]
    request_line = parts[2]
    after_request = parts[3]
    referer = parts[4]
    between = parts[5]
    user_agent = parts[6]

    # Check that prefix ends with ]
    if (substr(prefix, length(prefix), 1) != "]") {
        malformed++
        next
    }

    # Find the last [ in prefix.
    last_bracket = 0
    for (i = 1; i <= length(prefix); i++) {
        if (substr(prefix, i, 1) == "[") {
            last_bracket = i
        }
    }

    if (last_bracket == 0) {
        malformed++
        next
    }

    # The part before the [ is "IP ident user "
    pre_date = substr(prefix, 1, last_bracket - 1)

    # Parse pre_date: should have 3 fields: IP, ident, user
    npd = split(pre_date, pd_parts, " ")
    if (npd < 3) {
        malformed++
        next
    }

    ip = pd_parts[1]

    # Validate IP: should be non-empty
    if (ip == "") {
        malformed++
        next
    }

    # Parse the request line: METHOD path protocol
    nr = split(request_line, req_parts, " ")
    if (nr < 2) {
        malformed++
        next
    }
    method = req_parts[1]
    full_path = req_parts[2]

    # Extract path without query string
    qpos = index(full_path, "?")
    if (qpos > 0) {
        path = substr(full_path, 1, qpos - 1)
    } else {
        path = full_path
    }

    # Parse after_request: should be " status size "
    # Trim leading/trailing spaces
    gsub(/^[ \t]+|[ \t]+$/, "", after_request)

    na = split(after_request, after_parts, " ")
    if (na < 2) {
        malformed++
        next
    }

    status_str = after_parts[1]
    size_str = after_parts[2]

    # Validate status: must be numeric
    if (status_str !~ /^[0-9]+$/) {
        malformed++
        next
    }

    status = int(status_str)

    # Parse size: can be a number or "-"
    if (size_str == "-") {
        size = 0
    } else if (size_str ~ /^[0-9]+$/) {
        size = int(size_str)
    } else {
        malformed++
        next
    }

    # Valid line!
    requests++

    # Count status codes
    status_count[status]++

    # Sum bytes by IP
    ip_bytes[ip] += size

    # Count paths
    path_count[path]++
}
END {
    print "requests: " requests
    print "malformed: " malformed

    print "status:"
    # Sort status codes ascending. Collect all unique status codes and sort them.
    n_status = 0
    for (s in status_count) {
        n_status++
        status_codes[n_status] = s + 0  # Convert to number for sorting
    }
    # Simple insertion sort for status codes
    for (i = 2; i <= n_status; i++) {
        key = status_codes[i]
        j = i - 1
        while (j > 0 && status_codes[j] > key) {
            status_codes[j + 1] = status_codes[j]
            j--
        }
        status_codes[j + 1] = key
    }
    for (i = 1; i <= n_status; i++) {
        s = status_codes[i]
        printf "  %d %d\n", s, status_count[s]
    }

    print "top_ips:"
    # Top 3 IPs by total bytes, ties broken by IP ascending in byte order (lexicographic)
    n_ips = 0
    for (ip in ip_bytes) {
        n_ips++
        ip_list[n_ips] = ip
    }
    # Sort: primary by bytes descending, secondary by IP ascending (lexicographic)
    # Insertion sort
    for (i = 2; i <= n_ips; i++) {
        key_ip = ip_list[i]
        key_bytes = ip_bytes[key_ip]
        j = i - 1
        while (j > 0 && (ip_bytes[ip_list[j]] < key_bytes || (ip_bytes[ip_list[j]] == key_bytes && ip_list[j] > key_ip))) {
            ip_list[j + 1] = ip_list[j]
            j--
        }
        ip_list[j + 1] = key_ip
    }

    top_n = n_ips
    if (top_n > 3) top_n = 3
    for (i = 1; i <= top_n; i++) {
        printf "  %s %d\n", ip_list[i], ip_bytes[ip_list[i]]
    }

    print "top_paths:"
    # Top 3 paths by count descending, ties by path ascending (lexicographic)
    n_paths = 0
    for (p in path_count) {
        n_paths++
        path_list[n_paths] = p
    }
    # Insertion sort
    for (i = 2; i <= n_paths; i++) {
        key_path = path_list[i]
        key_count = path_count[key_path]
        j = i - 1
        while (j > 0 && (path_count[path_list[j]] < key_count || (path_count[path_list[j]] == key_count && path_list[j] > key_path))) {
            path_list[j + 1] = path_list[j]
            j--
        }
        path_list[j + 1] = key_path
    }

    top_n = n_paths
    if (top_n > 3) top_n = 3
    for (i = 1; i <= top_n; i++) {
        printf "  %s %d\n", path_list[i], path_count[path_list[i]]
    }
}
