    # Let us assume if header_found is still 0 and we have no data, it is fine for empty files?
    # The problem says "CSV file with a header row", so there should be at least one line.

    if (sum_mode == "1") {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min_val, max_val
        }
    }
}
