                            print "Error: Unknown column #" col_index > "/dev/stderr"
                            exit 3
                        }
                        col_index = col_index - 1  # Convert to 0-based
                    }
                } else {
                    # This is a data row
                    if (col_index >= fields_count) {
                        # Row has fewer fields than header, treat as empty
                        val = ""
                    } else {
                        val = fields[col_index]
                    }

                    if (sum_mode == "1") {
                        # Check if numeric
                        if (val != "" && val ~ /^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$/) {
                            num = val + 0
                            count++
                            sum_val += num
                            if (count == 1) {
                                min_val = num
                                max_val = num
                            } else {
                                if (num < min_val) min_val = num
                                if (num > max_val) max_val = num
                            }
                        }
                    } else {
                        # Print value, replacing embedded newlines with literal \n
                        out = ""
                        vlen = length(val)
                        for (vi = 1; vi <= vlen; vi++) {
                            vc = substr(val, vi, 1)
                            if (vc == "\n") {
                                out = out "\\n"
                            } else {
                                out = out vc
                            }
                        }
                        print out
                    }
                }

                fields_count = 0
            } else if (ch == "\r") {
                # Skip \r, it is part of \r\n line ending
                pos++
                continue
            } else {
                current_field = current_field ch
            }
        }

        pos++
    }

    # Check if we ended while still in quotes (unterminated quote)
    if (in_quotes) {
        print "Error: Unterminated quote" > "/dev/stderr"
        exit 4
    }

    if (sum_mode == "1") {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum_val, min_val, max_val
        }
    }
}
