BEGIN {
    # Track seen keys for deduplication (later wins, keep last position)
    # We store lines in order, but only print each key once at its last occurrence.
    count = 0
}

{
    lineno = NR
    line = $0

    # Remove trailing CR if present (handle Windows line endings)
