        # The spec says "optional leading export ". So "exportKEY=val" is not valid because KEY must follow space.
        print FILE ":" lineno ": invalid line" > "/dev/stderr"
        exit 1
    }

    # Now work should be KEY=VALUE
    # Find the first = sign
    eq_pos = index(work, "=")
