        # After closing quote must be empty or a comment
        after_trimmed = after_quote
        gsub(/^[[:space:]]+/, "", after_trimmed)
        if (after_trimmed != "" && substr(after_trimmed, 1, 1) != "#") {
            print FILE ":" lineno ": invalid line" > "/dev/stderr"
            exit 1
        }

    } else {
        # Unquoted value: taken literally up to an unquoted " #" (space then hash)
        # Trailing spaces and tabs are trimmed.

