        # Actually, for unquoted, we look for " #" pattern. But we need to be careful: a#b keeps the hash.
        # So we look for a space followed by # where the space is part of the value separator.

        # Strategy: scan through the string, find first position where we have " #" and it's not preceded by another space that is part of trailing? No.
        # The spec says: taken literally up to an unquoted " #". This means the first occurrence of a space followed by # ends the value.
        # But what about "a#b"? There is no space before #, so it keeps the hash.
        # What about "a b # c"? The value would be "a b" because " #" appears after "b ".

        # Let's find the first index where we have a space and the next char is #.
        val_str = ""
        len_val = length(value_part_trimmed)
        found_comment = 0
        for (i = 1; i <= len_val; i++) {
