                }
            }
            if (!found_comment) {
                val_str = val_str c
            }
        }

        if (!found_comment) {
            val_str = value_part_trimmed
        }

        # Trim trailing spaces and tabs from val_str
        gsub(/[[:space:]]+$/, "", val_str)
    }

    # Store key and value. Use an associative array to track last occurrence position.
    # We need to output in input order, but only once per key at its last occurrence.
    # So we record the line number of the last occurrence for each key.

    last_pos[key] = count
    values[key] = val_str

    # Add to ordered list if this is the first time we see this key
    if (!(key in seen_keys)) {
        seen_keys[key] = 1
        order[count] = key
        count++
    } else {
        # Key repeated: remove from old position and add to new end? 
        # No, spec says "keeps its LATER position (print it once, at its last occurrence)".
        # So we need to move the key to the end of the order list.

        # Find and remove old index
        for (j = 0; j < count; j++) {
            if (order[j] == key) {
