                for (k = j; k < count - 1; k++) {
                    order[k] = order[k + 1]
                }
                count--
                break
            }
        }

        # Add to end
        order[count] = key
        count++
    }
}

END {
    for (i = 0; i < count; i++) {
        k = order[i]
        v = values[k]

